program:
Let("loop", Fn(["n", "history"],
  Let("s", Eval("sample", {"prompt": Concat("You are playing 20 questions. The user is thinking of a word and answers each question. So far:\n", Ref("history"), "\nAsk one concise yes/no question that best narrows down the word. If you are confident of the word, ask 'Is the word X?' instead. Reply with only the question.")}),
    Let("q", Get(Ref("s"), "text"),
      Let("a", Eval("ask", {"message": Concat("Question ", Ref("n"), " of 20: ", Ref("q"), "\nReply yes, no, or sometimes. Reply 'correct' if you are saying yes to an 'Is the word X?' question. Reply 'quit' to stop.")}),
        If(Eq(Get(Ref("a"), "action"), "accept"),
          Let("r", Get(Get(Ref("a"), "content"), "reply"),
            If(Eq(Ref("r"), "correct"),
              Construct({"status": "won", "questionsUsed": Ref("n"), "history": Ref("history")}),
              If(Eq(Ref("r"), "quit"),
                Construct({"status": "quit", "questionsUsed": Ref("n"), "history": Ref("history")}),
                If(Gt(Ref("n"), 19),
                  Construct({"status": "out_of_questions", "questionsUsed": Ref("n"), "history": Ref("history")}),
                  Call(Ref("loop"), Add(Ref("n"), 1), Concat(Ref("history"), "\nQ: ", Ref("q"), "\nA: ", Ref("r")))
                )
              )
            )
          ),
          Construct({"status": Get(Ref("a"), "action"), "questionsUsed": Ref("n"), "history": Ref("history")})
        )
      )
    )
  )
), Call(Ref("loop"), 1, ""))
